struct Tup0 { int a; int b; I32 cost;
    auto tie() const { return std::tie(a, b, cost); }
    template <class H> size_t cp_hash(const H& hf) const { size_t h = 0; h = h * 0x9e3779b97f4a7c15ULL + hf((ll)a); h = h * 0x9e3779b97f4a7c15ULL + hf((ll)b); h = h * 0x9e3779b97f4a7c15ULL + hf((ll)cost); return h; }
    bool operator<(const Tup0& o) const { return tie() < o.tie(); }
    bool operator>(const Tup0& o) const { return o.tie() < tie(); }
    bool operator==(const Tup0& o) const { return tie() == o.tie(); }
    bool operator!=(const Tup0& o) const { return !(*this == o); } };

struct Tup1 { int a; int b; I32 cost;
    auto tie() const { return std::tie(a, b, cost); }
    template <class H> size_t cp_hash(const H& hf) const { size_t h = 0; h = h * 0x9e3779b97f4a7c15ULL + hf((ll)a); h = h * 0x9e3779b97f4a7c15ULL + hf((ll)b); h = h * 0x9e3779b97f4a7c15ULL + hf((ll)cost); return h; }
    bool operator<(const Tup1& o) const { return tie() < o.tie(); }
    bool operator>(const Tup1& o) const { return o.tie() < tie(); }
    bool operator==(const Tup1& o) const { return tie() == o.tie(); }
    bool operator!=(const Tup1& o) const { return !(*this == o); } };

struct E_Link { int tag = 0; union { struct { int Flight_a; int Flight_b; }; struct { int Portal_a; int Portal_b; }; };
    E_Link() { memset((void*)this, 0, sizeof *this); }
    bool operator==(const E_Link& o) const { return tag == o.tag && (tag == 0 ? (Flight_a == o.Flight_a && Flight_b == o.Flight_b) : tag == 1 ? (Portal_a == o.Portal_a && Portal_b == o.Portal_b) : true); }
    bool operator!=(const E_Link& o) const { return !(*this == o); } };

template <> struct Opt<E_Link> { E_Link v; Opt() { v.tag = -1; } Opt(const E_Link& x) : v(x) {}
    bool has() const { return v.tag >= 0; } const E_Link& get() const { return v; }
    bool operator==(const Opt& o) const { return has() == o.has() && (!has() || v == o.v); }
    bool operator!=(const Opt& o) const { return !(*this == o); } };

struct Tup2 { ll cost; E_Link link_;
    auto tie() const { return std::tie(cost, link_); }
    bool operator==(const Tup2& o) const { return tie() == o.tie(); }
    bool operator!=(const Tup2& o) const { return !(*this == o); } };

